const game = new GF.Game({ id: 'core-awakening', title: 'Core Awakening', palette: ['#00BFFF', '#FFD700', '#C0C0C0', '#FF4500'], background: '#0b0e1a' });

let player = { x: 480, y: 270, size: 20, color: '#FFD700' };
let enemies = [];
let enemySpawnTime = 1;
let backgroundElements = [];

const spawnEnemy = () => {
  enemies.push({ x: GF.math.rand(0, game.W), y: -20, size: 30, color: '#FF4500', speed: GF.math.rand(50, 100) });
};

const spawnBackgroundElement = () => {
  backgroundElements.push({ x: GF.math.rand(0, game.W), y: GF.math.rand(0, game.H), size: GF.math.rand(10, 50), color: '#C0C0C0', speed: GF.math.rand(20, 50) });
};

setInterval(spawnBackgroundElement, 2000);

game.add('play', {
  init() {
    this.score = 0;
    this.time = 0;
    enemies = [];
    backgroundElements = [];
    game.addScore(0);
    setInterval(spawnEnemy, enemySpawnTime * 1000);
  },
  update(dt) {
    this.time += dt;
    if (game.input.pressed('Space')) {
      game.hitStop(0.1);
      game.flash('#FFD700', 0.5);
      game.addScore(1);
      GF.Sfx.beep({ freq: 600, dur: 0.1 });
    }
    enemies.forEach((enemy, index) => {
      enemy.y += enemy.speed * dt;
      if (enemy.y > game.H) {
        enemies.splice(index, 1);
        game.gameOver({ message: 'You were overwhelmed!' });
      }
      if (GF.math.dist(player.x, player.y, enemy.x, enemy.y) < player.size + enemy.size) {
        game.shake(5, 0.2);
        game.hitStop(0.1);
        enemies.splice(index, 1);
        game.addScore(1);
        game.burst(enemy.x, enemy.y, { count: 10, speed: 100, size: 5, life: 0.5, colors: ['#FFD700', '#FF4500'] });
        GF.Sfx.noise({ dur: 0.2, vol: 0.5 });
      }
    });
    backgroundElements.forEach(element => {
      element.y += element.speed * dt;
      if (element.y > game.H) {
        element.y = 0;
        element.x = GF.math.rand(0, game.W);
      }
    });
  },
  draw(ctx) {
    ctx.fillStyle = '#0b0e1a';
    ctx.fillRect(0, 0, game.W, game.H);
    backgroundElements.forEach(element => {
      ctx.fillStyle = element.color;
      ctx.beginPath();
      ctx.arc(element.x, element.y, element.size, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.fillStyle = player.color;
    ctx.beginPath();
    ctx.arc(player.x, player.y, player.size, 0, Math.PI * 2);
    ctx.fill();
    enemies.forEach(enemy => {
      ctx.fillStyle = enemy.color;
      ctx.beginPath();
      ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
      ctx.fill();
    });
    GF.Draw.text(ctx, String(this.score), game.W / 2, 44, { size: 34, color: 'rgba(255,255,255,0.92)' });
  }
});

game.titleScreen({
  subtitle: 'Press any key to start',
  onStart: () => game.go('play')
});
